"""
Flatten hierarchical policy->claims extraction into flat claim records.

Converts the hierarchical extraction output (policies with nested claims arrays)
into a flat list of claim records where each claim includes its parent policy's fields.
Policies with no claims are preserved as marker records for aggregation.
"""


async def run(data=None, schema=None, **kwargs):
    """
    Flatten hierarchical policy->claims extraction into flat claim records.

    For each policy object:
    - If it has claims: create one flat record per claim, copying policy fields down
    - If it has NO claims: create a marker record with policy fields and null claim fields

    Args:
        data: List of policy objects from Extract Policies step (each with nested claims)
        schema: Input schema from Extract Policies step
        **kwargs: Additional workflow context

    Returns:
        dict: Contains 'data' (flat claim list) and 'schema' (flat claim schema)
    """
    from fai_sandbox import log

    POLICY_FIELDS = [
        "insurer_organization",
        "doc_gen_date",
        "insured_entity",
        "agent_org",
        "policy_number",
        "policy_effective_date",
        "policy_expiration_date",
        "line_of_business",
    ]

    CLAIM_FIELDS = [
        "coverage",
        "claim_number",
        "claim_status",
        "claim_adjuster",
        "claimant",
        "claim_incident_date",
        "claim_reported_date",
        "claim_closed_date",
        "claim_description",
        "claim_state",
        "indemnity_paid",
        "indemnity_reserve",
        "property_damage_paid",
        "property_damage_reserve",
        "medical_paid",
        "medical_reserve",
        "expense_other_paid",
        "expense_other_reserve",
        "recovered",
    ]

    # Define flat output schema matching the existing flat claim schema structure
    output_schema = {
        "type": "array",
        "items": {
            "type": "object",
            "properties": {
                field: {"type": "string"}
                for field in POLICY_FIELDS
            },
        },
    }
    # Add claim fields to output schema
    for field in CLAIM_FIELDS:
        if field in (
            "indemnity_paid", "indemnity_reserve",
            "property_damage_paid", "property_damage_reserve",
            "medical_paid", "medical_reserve",
            "expense_other_paid", "expense_other_reserve",
            "recovered",
        ):
            output_schema["items"]["properties"][field] = {"type": "number"}
        else:
            output_schema["items"]["properties"][field] = {"type": "string"}

    if not data:
        log.warning("No policy data to flatten")
        return {"data": [], "schema": output_schema}

    # Debug: log structure of first policy to understand data format
    if data and len(data) > 0:
        first_policy = data[0]
        log.info("[FLATTEN_DEBUG] Total policies received", count=len(data))
        log.info("[FLATTEN_DEBUG] First policy keys", keys=list(first_policy.keys()) if isinstance(first_policy, dict) else str(type(first_policy)))
        claims_raw = first_policy.get("claims") if isinstance(first_policy, dict) else None
        log.info("[FLATTEN_DEBUG] First policy 'claims' type", type=str(type(claims_raw)))
        if isinstance(claims_raw, list):
            log.info("[FLATTEN_DEBUG] First policy 'claims' length", length=len(claims_raw))
            if len(claims_raw) > 0:
                log.info("[FLATTEN_DEBUG] First claim keys", keys=list(claims_raw[0].keys()) if isinstance(claims_raw[0], dict) else str(type(claims_raw[0])))
        elif isinstance(claims_raw, dict):
            log.info("[FLATTEN_DEBUG] First policy 'claims' dict keys", keys=list(claims_raw.keys()))
            if "value" in claims_raw:
                inner = claims_raw["value"]
                log.info("[FLATTEN_DEBUG] First policy 'claims.value' type", type=str(type(inner)), length=len(inner) if isinstance(inner, list) else "N/A")
        else:
            log.info("[FLATTEN_DEBUG] First policy 'claims' value", value=claims_raw)

    flat_claims = []
    total_policies = 0
    empty_policies = 0

    for policy in data:
        total_policies += 1

        # Extract policy-level fields, preserving TableV1 cell format {value, confidence_score, ...}
        policy_fields = {}
        for field in POLICY_FIELDS:
            policy_fields[field] = policy.get(field)

        # Get claims array from the policy
        claims = policy.get("claims")

        # Handle TableV1 cell format: claims might be wrapped in {value: [...]}
        if isinstance(claims, dict) and "value" in claims:
            claims = claims["value"]

        if claims and isinstance(claims, list) and len(claims) > 0:
            # Policy has claims: create one flat record per claim
            for claim in claims:
                record = {}
                # Copy policy fields
                for field in POLICY_FIELDS:
                    record[field] = policy_fields[field]
                # Copy claim fields
                for field in CLAIM_FIELDS:
                    record[field] = claim.get(field)
                flat_claims.append(record)
        else:
            # Policy with no claims: emit a marker record
            empty_policies += 1
            record = {}
            # Copy policy fields
            for field in POLICY_FIELDS:
                record[field] = policy_fields[field]
            # Set null claim fields
            for field in CLAIM_FIELDS:
                record[field] = {"value": None, "confidence_score": "HIGH", "citations": [], "thinking_steps": []}
            # Mark as no-claims policy for aggregation
            record["_no_claims_policy"] = {"value": True, "confidence_score": "HIGH", "citations": [], "thinking_steps": []}
            flat_claims.append(record)

    log.info(
        "Flattened policies into records",
        total_policies=total_policies,
        flat_records=len(flat_claims),
        empty_policies=empty_policies,
    )

    return {"data": flat_claims, "schema": output_schema}

"""
Loss Runs Aggregation function for hierarchical extraction workflow.

Aggregates flattened claims data by policy period to provide policy-level loss summaries.
Handles policies with no claims (from the flatten step's _no_claims_policy marker).
"""


async def run(data=None, schema=None, **kwargs):
    """
    Aggregate claims by policy period to provide policy-level loss summaries.

    Groups individual claims by policy number and period, calculating:
    - Total number of claims per policy
    - Total incurred amounts (paid + reserves - recoveries)
    - Financial breakdowns by component (indemnity, medical, property damage, expenses)

    Handles policies with no claims (marked by _no_claims_policy flag from flatten step),
    showing them with total_claims=0 and all financials=0.

    Args:
        data: List of flat claim records from Flatten Policies to Claims step
        schema: Input schema from Flatten Policies to Claims step
        **kwargs: Additional workflow context

    Returns:
        dict: Contains 'data' and 'schema' keys for table output
    """
    import pandas as pd
    from fai_sandbox import log

    # Define schema for the aggregated output (column order: who → when → what → how much → reference)
    output_schema = {
        "type": "array",
        "items": {
            "type": "object",
            "properties": {
                "insurer_organization": {"type": "string", "title": "Insurance Carrier"},
                "policy_effective_date": {"type": "string", "title": "Policy Effective Date"},
                "policy_expiration_date": {"type": "string", "title": "Policy Expiration Date"},
                "line_of_business": {"type": "string", "title": "Lines of Business"},
                "coverage": {"type": "string", "title": "Coverage Type"},
                "loss_run_valuation_date": {"type": "string", "title": "Valuation Date"},
                "total_claims": {"type": "integer", "title": "Total Claims"},
                "total_incurred": {"type": "number", "title": "Total Incurred"},
                "total_paid": {"type": "number", "title": "Total Paid"},
                "total_reserve": {"type": "number", "title": "Total Reserve"},
                "policy_number": {"type": "string", "title": "Policy Number"},
                "insured_entity": {"type": "string", "title": "Insured Entity"},
                "agent_org": {"type": "string", "title": "Agent/Broker"},
            },
        },
    }

    if not data:
        log.warning("No claims data to aggregate")
        return {"data": [], "schema": output_schema}

    df = pd.DataFrame(data)
    log.info("Aggregating records (including no-claims policy markers)", record_count=len(df))

    # Extract .value from dict objects (Reducto returns fields as dicts with value, confidence, citations)
    for col in df.columns:
        if df[col].apply(lambda x: isinstance(x, dict) and "value" in x).any():
            df[col] = df[col].apply(lambda x: x["value"] if isinstance(x, dict) and "value" in x else x)

    # Separate real claims from no-claims policy markers
    has_marker = "_no_claims_policy" in df.columns
    if has_marker:
        empty_policies_df = df[df["_no_claims_policy"] == True].copy()  # noqa: E712
        claims_df = df[df["_no_claims_policy"] != True].copy()  # noqa: E712
        log.info("Found no-claims policy markers and real claims", empty_policy_count=len(empty_policies_df), claim_count=len(claims_df))
    else:
        empty_policies_df = pd.DataFrame()
        claims_df = df.copy()

    # --- Aggregate real claims ---
    aggregated_claims = pd.DataFrame()

    if len(claims_df) > 0:
        # Ensure all financial fields are numeric
        financial_fields = [
            "indemnity_paid",
            "indemnity_reserve",
            "property_damage_paid",
            "property_damage_reserve",
            "medical_paid",
            "medical_reserve",
            "expense_other_paid",
            "expense_other_reserve",
        ]

        for field in financial_fields:
            if field in claims_df.columns:
                claims_df[field] = pd.to_numeric(claims_df[field], errors="coerce").fillna(0)

        if "recovered" in claims_df.columns:
            claims_df["recovered"] = pd.to_numeric(claims_df["recovered"], errors="coerce").fillna(0)
        else:
            claims_df["recovered"] = 0

        # Calculate total incurred per claim (paid + reserves - recoveries)
        claims_df["total_paid"] = (
            (claims_df["indemnity_paid"].fillna(0) if "indemnity_paid" in claims_df.columns else 0)
            + (claims_df["property_damage_paid"].fillna(0) if "property_damage_paid" in claims_df.columns else 0)
            + (claims_df["medical_paid"].fillna(0) if "medical_paid" in claims_df.columns else 0)
            + (claims_df["expense_other_paid"].fillna(0) if "expense_other_paid" in claims_df.columns else 0)
        )

        claims_df["total_reserve"] = (
            (claims_df["indemnity_reserve"].fillna(0) if "indemnity_reserve" in claims_df.columns else 0)
            + (claims_df["property_damage_reserve"].fillna(0) if "property_damage_reserve" in claims_df.columns else 0)
            + (claims_df["medical_reserve"].fillna(0) if "medical_reserve" in claims_df.columns else 0)
            + (claims_df["expense_other_reserve"].fillna(0) if "expense_other_reserve" in claims_df.columns else 0)
        )

        claims_df["total_incurred"] = claims_df["total_paid"] + claims_df["total_reserve"] - claims_df["recovered"]

        # Convert any dict/list columns to strings before grouping
        for col in claims_df.columns:
            if claims_df[col].apply(lambda x: isinstance(x, (dict, list))).any():
                claims_df[col] = claims_df[col].apply(lambda x: str(x) if isinstance(x, (dict, list)) else x)

        # Determine grouping columns (policy number + dates if available)
        group_cols = []

        if "policy_number" in claims_df.columns and claims_df["policy_number"].notna().any():
            group_cols.append("policy_number")
            if "policy_effective_date" in claims_df.columns and claims_df["policy_effective_date"].notna().any():
                group_cols.append("policy_effective_date")
            if "policy_expiration_date" in claims_df.columns and claims_df["policy_expiration_date"].notna().any():
                group_cols.append("policy_expiration_date")
            if "coverage" in claims_df.columns and claims_df["coverage"].notna().any():
                group_cols.append("coverage")
        else:
            log.warning("No policy_number available, attempting to group by policy dates")
            if "policy_effective_date" in claims_df.columns and claims_df["policy_effective_date"].notna().any():
                group_cols.append("policy_effective_date")
            if "policy_expiration_date" in claims_df.columns and claims_df["policy_expiration_date"].notna().any():
                group_cols.append("policy_expiration_date")
            if "coverage" in claims_df.columns and claims_df["coverage"].notna().any():
                group_cols.append("coverage")

        if not group_cols:
            log.warning("No policy grouping columns found, aggregating all claims as single group")
            aggregated_claims = pd.DataFrame(
                [
                    {
                        "total_claims": len(claims_df),
                        "total_paid": claims_df["total_paid"].sum(),
                        "total_reserve": claims_df["total_reserve"].sum(),
                        "total_incurred": claims_df["total_incurred"].sum(),
                        "insurer_organization": str(claims_df["insurer_organization"].iloc[0])
                        if "insurer_organization" in claims_df.columns
                        and len(claims_df) > 0
                        and pd.notna(claims_df["insurer_organization"].iloc[0])
                        else "",
                        "insured_entity": str(claims_df["insured_entity"].iloc[0])
                        if "insured_entity" in claims_df.columns
                        and len(claims_df) > 0
                        and pd.notna(claims_df["insured_entity"].iloc[0])
                        else "",
                        "line_of_business": ", ".join(
                            sorted(set(str(x) for x in claims_df["line_of_business"].dropna()))
                        )
                        if "line_of_business" in claims_df.columns
                        else "",
                    }
                ]
            )
        else:
            agg_dict = {
                "claim_number": "count",
                "total_paid": "sum",
                "total_reserve": "sum",
                "total_incurred": "sum",
            "coverage": "first",
            "doc_gen_date": "first",
            }

            for col in ["insurer_organization", "insured_entity", "agent_org"]:
                if col in claims_df.columns:
                    agg_dict[col] = "first"

            if "line_of_business" in claims_df.columns:
                agg_dict["line_of_business"] = lambda x: ", ".join(sorted(set(str(v) for v in x.dropna())))

            aggregated_claims = claims_df.groupby(group_cols, as_index=False, dropna=False).agg(agg_dict)
            aggregated_claims.rename(columns={"claim_number": "total_claims"}, inplace=True)

    # --- Build empty policy rows ---
    empty_policy_rows = []

    if len(empty_policies_df) > 0:
        # Convert any dict/list columns to strings
        for col in empty_policies_df.columns:
            if empty_policies_df[col].apply(lambda x: isinstance(x, (dict, list))).any():
                empty_policies_df[col] = empty_policies_df[col].apply(
                    lambda x: str(x) if isinstance(x, (dict, list)) else x
                )

        for _, row in empty_policies_df.iterrows():
            empty_policy_rows.append(
                {
                    "policy_number": row.get("policy_number", ""),
                    "policy_effective_date": row.get("policy_effective_date", ""),
                    "policy_expiration_date": row.get("policy_expiration_date", ""),
                    "insurer_organization": row.get("insurer_organization", ""),
                    "insured_entity": row.get("insured_entity", ""),
                    "agent_org": row.get("agent_org", ""),
                    "line_of_business": row.get("line_of_business", ""),
                    "total_claims": 0,
                    "total_paid": 0.0,
                    "total_reserve": 0.0,
                    "total_incurred": 0.0,
                    "coverage": "",
                    "doc_gen_date": "",
                }
            )

    # --- Combine all rows into a single DataFrame for sorting ---
    all_rows = []

    if len(aggregated_claims) > 0:
        for _, row in aggregated_claims.iterrows():
            all_rows.append(row.to_dict() if hasattr(row, "to_dict") else row)

    for row_data in empty_policy_rows:
        all_rows.append(row_data)

    # Sort by insurer_organization (ascending), then policy_effective_date (newest first)
    if all_rows:
        combined_df = pd.DataFrame(all_rows)

        # Parse policy_effective_date for proper date sorting
        if "policy_effective_date" in combined_df.columns:
            combined_df["_sort_date"] = pd.to_datetime(combined_df["policy_effective_date"], errors="coerce")
        else:
            combined_df["_sort_date"] = pd.NaT

        if "insurer_organization" in combined_df.columns:
            combined_df["_sort_org"] = combined_df["insurer_organization"].fillna("").astype(str)
        else:
            combined_df["_sort_org"] = ""

        combined_df.sort_values(
            by=["_sort_org", "_sort_date"],
            ascending=[True, False],
            na_position="last",
            inplace=True,
        )
        combined_df.drop(columns=["_sort_date", "_sort_org"], inplace=True)
        all_rows = [row.to_dict() for _, row in combined_df.iterrows()]

    # --- Convert to TableV1 format ---
    output_data = []
    for row_data in all_rows:
        output_data.append(_to_tablev1_row(row_data))

    log.info(
        "Aggregated claims into policy summaries",
        claim_count=len(claims_df),
        policy_summary_count=len(aggregated_claims) if len(aggregated_claims) > 0 else 0,
        empty_policy_count=len(empty_policy_rows),
    )
    total_output = len(output_data)
    log.info("Total output rows", row_count=total_output)

    return {"data": output_data, "schema": output_schema}


def _to_tablev1_row(row_data):
    """Convert a row dict to TableV1 cell format."""
    import pandas as pd

    return {
        "insurer_organization": {
            "value": str(row_data.get("insurer_organization", ""))
            if pd.notna(row_data.get("insurer_organization"))
            else "",
            "confidence": "high",
        },
        "policy_effective_date": {
            "value": str(row_data.get("policy_effective_date", ""))
            if pd.notna(row_data.get("policy_effective_date"))
            else "",
            "confidence": "high",
        },
        "policy_expiration_date": {
            "value": str(row_data.get("policy_expiration_date", ""))
            if pd.notna(row_data.get("policy_expiration_date"))
            else "",
            "confidence": "high",
        },
        "line_of_business": {
            "value": str(row_data.get("line_of_business", ""))
            if pd.notna(row_data.get("line_of_business"))
            else "",
            "confidence": "high",
        },
        "total_claims": {
            "value": int(row_data.get("total_claims", 0)) if pd.notna(row_data.get("total_claims")) else 0,
            "confidence": "high",
        },
        "total_incurred": {
            "value": round(float(row_data.get("total_incurred", 0)), 2)
            if pd.notna(row_data.get("total_incurred"))
            else 0.0,
            "confidence": "high",
        },
        "total_paid": {
            "value": round(float(row_data.get("total_paid", 0)), 2)
            if pd.notna(row_data.get("total_paid"))
            else 0.0,
            "confidence": "high",
        },
        "total_reserve": {
            "value": round(float(row_data.get("total_reserve", 0)), 2)
            if pd.notna(row_data.get("total_reserve"))
            else 0.0,
            "confidence": "high",
        },
        "policy_number": {
            "value": str(row_data.get("policy_number", "")) if pd.notna(row_data.get("policy_number")) else "",
            "confidence": "high",
        },
        "insured_entity": {
            "value": str(row_data.get("insured_entity", "")) if pd.notna(row_data.get("insured_entity")) else "",
            "confidence": "high",
        },
        "agent_org": {
            "value": str(row_data.get("agent_org", "")) if pd.notna(row_data.get("agent_org")) else "",
            "confidence": "high",
        },
        "coverage": {
            "value": str(row_data.get("coverage", "")) if pd.notna(row_data.get("coverage")) else "",
            "confidence": "high",
        },
        "loss_run_valuation_date": {
            "value": str(row_data.get("doc_gen_date", "")) if pd.notna(row_data.get("doc_gen_date")) else "",
            "confidence": "high",
        },
    }

def run(basic_info_raw=None, **kwargs):
    """Extract insured name, DBA names, and address for OFAC sanctions check."""
    data = basic_info_raw or {}
    if isinstance(data, dict) and "data" in data:
        data = data["data"]

    def get_val(d, key):
        v = d.get(key)
        if isinstance(v, dict) and "value" in v:
            return str(v["value"]).strip() if v["value"] else ""
        return str(v).strip() if v else ""

    insured_name = get_val(data, "insured_name") or "Unknown"

    # DBA names as aliases
    dba_raw = data.get("dba_names")
    aliases = []
    if isinstance(dba_raw, dict) and "value" in dba_raw:
        dba_raw = dba_raw["value"]
    if isinstance(dba_raw, list):
        aliases = [str(x.get("value", x) if isinstance(x, dict) else x).strip() for x in dba_raw if x]
    elif isinstance(dba_raw, str) and dba_raw.strip():
        aliases = [dba_raw.strip()]

    address = {
        "line_1": get_val(data, "premises_street"),
        "city": get_val(data, "premises_city"),
        "state": get_val(data, "premises_state"),
        "postal_code": get_val(data, "premises_zip"),
    }

    return {"Insured name": insured_name, "aliases": aliases, "address": address}

