async def run(standardized_data=None, flatten_claims_data=None, acord_126_data=None, **kwargs):
    """Collect all extraction outputs into a single data_points list for the AI summary."""
    from fai_sandbox import log

    data = standardized_data or {}
    data_points = []

    section_names = {
        'basic_info': 'Basic Insured Information',
        'broker_uw': 'Broker and Underwriter Information',
        'additional_policy': 'Additional Policy Information',
        'underlying_coverage': 'Underlying Coverage',
        'auto_schedule': 'Auto Schedule',
        'expiring_account': 'Expiring Account Information',
        'aggregated_loss_data': 'Aggregated Loss Run Data',
    }

    for key, title in section_names.items():
        section = data.get(key)
        if section:
            if isinstance(section, dict):
                data_points.append({title: section})
            elif isinstance(section, list) and section:
                data_points.append({title: section})

    # Filter and format individual claims >$25k
    if flatten_claims_data:
        claims = flatten_claims_data if isinstance(flatten_claims_data, list) else (flatten_claims_data.get('data', []) if isinstance(flatten_claims_data, dict) else [])
        if claims:
            def unwrap(val):
                if isinstance(val, dict) and 'value' in val:
                    return val['value']
                return val

            def safe_float(val):
                if val is None:
                    return 0.0
                try:
                    return float(str(val).replace('$', '').replace(',', '').strip()) if val else 0.0
                except (ValueError, TypeError):
                    return 0.0

            def fmt_currency(num):
                if num == 0:
                    return None
                try:
                    if num == int(num):
                        return f'${int(num):,}'
                    return f'${num:,.2f}'
                except (ValueError, TypeError, OverflowError):
                    return f'${num}'

            large_claims = []
            small_count = 0

            for claim in claims:
                if not isinstance(claim, dict):
                    continue

                # Calculate total incurred
                money_fields = ['indemnity_paid', 'indemnity_reserve', 'medical_paid', 'medical_reserve',
                                'expense_other_paid', 'expense_other_reserve', 'property_damage_paid', 'property_damage_reserve']
                total = sum(safe_float(unwrap(claim.get(f, 0))) for f in money_fields)

                if total >= 25000:
                    coverage = unwrap(claim.get('coverage', '')) or unwrap(claim.get('line_of_business', ''))
                    claim_num = unwrap(claim.get('claim_number', ''))
                    status = unwrap(claim.get('claim_status', ''))

                    # Build non-zero amount parts
                    parts = []
                    for field, label in [('indemnity_paid', 'indemnity paid'), ('indemnity_reserve', 'indemnity reserve'),
                                          ('medical_paid', 'medical paid'), ('medical_reserve', 'medical reserve'),
                                          ('property_damage_paid', 'property damage paid'), ('property_damage_reserve', 'property damage reserve'),
                                          ('expense_other_paid', 'expense paid'), ('expense_other_reserve', 'expense reserve')]:
                        v = safe_float(unwrap(claim.get(field, 0)))
                        if v > 0:
                            parts.append(f'{fmt_currency(v)} {label}')

                    detail = ', '.join(parts)
                    claim_ref = f' (Claim {claim_num})' if claim_num else ''
                    status_str = f' ({status})' if status else ''
                    large_claims.append(f'{coverage}{claim_ref}: {detail}{status_str}')
                else:
                    small_count += 1

            # Format as a pre-built HTML section
            if large_claims or small_count > 0:
                loss_html = '<b>Loss Details</b><ul>'
                for lc in large_claims:
                    loss_html += f'<li>{lc}</li>'
                loss_html += '</ul>'
                if small_count > 0:
                    loss_html += f'All other reported losses ({small_count} claims) are under $25,000.<br>'
                data_points.append({'Loss Details (claims over $25k)': loss_html})
                log.info('[COLLECT] Claims over/under $25k', over_25k=len(large_claims), under_25k=small_count)
            else:
                log.info('[COLLECT] No claims data to process')

    # Add ACORD 126
    if acord_126_data:
        acord_rows = acord_126_data if isinstance(acord_126_data, list) else (acord_126_data.get('data', []) if isinstance(acord_126_data, dict) else [])
        if acord_rows:
            data_points.append({'ACORD 126 GL Classification and Exposure': acord_rows})
            log.info('[COLLECT] Added ACORD 126 rows', row_count=len(acord_rows))

    log.info('[COLLECT] Total data_points', count=len(data_points))
    return {"data_points": data_points}

async def run(standardized_data=None, gc_alpha=None, gc_beta=None, gc_gamma=None, app_base_url=None, **kwargs):
    """Build an HTML summary dashboard for the ABC MGA submission.

    Inputs:
        standardized_data: from Standardize Extracted Data
        gc_alpha/gc_beta/gc_gamma: from Guideline Check steps (multi_column_qa output)
    Returns:
        {"email_body": "<html>...</html>"}
    """
    import html as html_module
    from fai_sandbox import context, log

    execution_log_id = context.execution_log().get("id", "")
    base_url = app_base_url or "https://app.furtherai.com"
    execution_url = base_url + "/workflow-execution/" + execution_log_id if execution_log_id else "#"

    # ── Helpers ──

    def esc(val):
        return html_module.escape(str(val)) if val else ""

    def get(d, key, default=""):
        if not d:
            return default
        v = d.get(key)
        if isinstance(v, dict) and "value" in v:
            v = v["value"]
        return str(v).strip() if v else default

    def extract_value(val):
        if isinstance(val, dict) and "value" in val:
            return str(val.get("value", "")).strip()
        if val is None or val == {} or val == []:
            return ""
        s = str(val).strip()
        if s in ('{}', '[]', 'None', 'null'):
            return ""
        return s

    # ── Extract data ──

    data = standardized_data or {}
    basic = data.get("basic_info", {})
    additional = data.get("additional_policy", {})
    coverage = data.get("underlying_coverage", {})
    auto = data.get("auto_schedule", {})
    expiring = data.get("expiring_account", {})
    agg_loss = data.get("aggregated_loss_data", [])

    insured_name = esc(get(basic, "Insured Name", "Unknown Insured"))
    business_type = esc(get(basic, "Business Type", ""))
    city = get(basic, "Insured Premises City", "")
    state = get(basic, "Insured Premises State", "")
    location = esc((city + ", " + state).strip(", ")) if city or state else ""
    eff_date = esc(get(basic, "Policy Effective Date", ""))
    exp_date = esc(get(additional, "Policy Expiration Date", ""))
    biz_desc = esc(get(basic, "Business Description", ""))
    desc_ops = esc(get(basic, "Description of Operations", ""))
    description = biz_desc or desc_ops

    # ── Process guideline checks ──

    def process_gc(gc_data, carrier_name):
        rows = []
        if gc_data and isinstance(gc_data, dict):
            raw = gc_data.get("data", [])
            if isinstance(raw, list):
                for row in raw:
                    guideline = extract_value(row.get("guideline", {}))
                    answer = extract_value(row.get("answer", {}))
                    finding = extract_value(row.get("finding", {}))
                    status_raw = extract_value(row.get("status", {}))

                    status = status_raw
                    for prefix in ["\u2705 ", "\u274c ", "\u26a0\ufe0f ", "\u26a0 "]:
                        if status.startswith(prefix):
                            status = status[len(prefix):]
                            break
                    status = status.strip()

                    detail = answer or finding or ""
                    rows.append({"guideline": guideline, "status": status, "detail": detail})

        pass_count = sum(1 for r in rows if r["status"] == "Pass")
        fail_count = sum(1 for r in rows if r["status"] == "Fail")
        review_count = sum(1 for r in rows if r["status"] in ("Needs Info", "Needs Review"))

        if fail_count > 0:
            badge_class = "badge-fail"
            parts = []
            if fail_count > 0:
                parts.append(str(fail_count) + " failed")
            if review_count > 0:
                parts.append(str(review_count) + " needs info")
            badge_text = " \u00b7 ".join(parts)
        elif review_count > 0:
            badge_class = "badge-review"
            badge_text = str(review_count) + " needs review"
        else:
            badge_class = "badge-pass"
            badge_text = "All passed"

        if fail_count > 0:
            hero_class = "fail"
            hero_text = carrier_name + ": " + str(fail_count) + " failed"
        elif review_count > 0:
            hero_class = "review"
            hero_text = carrier_name + ": " + str(review_count) + " needs review"
        else:
            hero_class = "pass"
            hero_text = carrier_name + ": All passed"

        return {
            "rows": rows, "pass_count": pass_count, "fail_count": fail_count,
            "review_count": review_count, "badge_class": badge_class,
            "badge_text": badge_text, "hero_class": hero_class,
            "hero_text": hero_text, "carrier": carrier_name,
        }

    carriers = [
        process_gc(gc_alpha, "Alpha"),
        process_gc(gc_beta, "Beta"),
        process_gc(gc_gamma, "Gamma"),
    ]

    # ── Hero badges ──

    hero_badges_html = ""
    for c in carriers:
        hero_badges_html += '<span class="hero-badge ' + c["hero_class"] + '">' + esc(c["hero_text"]) + '</span>'

    # ── Account Information rows ──

    premises_street = esc(get(basic, "Insured Premises Street", ""))
    premises_zip = esc(get(basic, "Insured/Premises ZIP", ""))
