    mailing_parts = [
        get(basic, "Insured Mailing Street", ""),
        get(basic, "Insured Mailing City", ""),
        get(basic, "Mailing State", ""),
        get(basic, "Insured Mailing ZIP", ""),
    ]
    mailing_full = esc(", ".join(p for p in mailing_parts if p))
    btype_desc = business_type
    if biz_desc:
        btype_desc = business_type + " \u2014 " + biz_desc if business_type else biz_desc

    account_html = ""
    account_rows = [
        ("Insured Name", insured_name, True),
        ("Premise Location", esc(premises_full), False),
        ("Mailing Address", mailing_full, False),
        ("Class / Type of Business", btype_desc, False),
        ("Description of Operations", esc(desc_ops), False),
        ("Policy Effective Date", eff_date, False),
    ]
    if exp_date:
        account_rows.append(("Policy Expiration Date", exp_date, False))

    for label, val, bold in account_rows:
        weight = ' style="font-weight:500;"' if bold else ""
        account_html += '<tr><td style="width:200px; color:#999;">' + label + '</td><td' + weight + '>' + val + '</td></tr>'

    # ── Exposure Information ──

    payroll = esc(get(additional, "Payroll", ""))
    receipts = esc(get(additional, "Receipts/Sales", ""))

    exposure_top = ""
    if payroll:
        exposure_top += '<tr><td style="width:200px; color:#999;">Payroll</td><td>$' + payroll + '</td></tr>'
    if receipts:
        exposure_top += '<tr><td style="color:#999;">Receipts / Sales</td><td>$' + receipts + '</td></tr>'

    GENERIC_AUTO_KEYS = [
        "Private Passenger Vehicles", "Light Trucks", "Medium Trucks",
        "Heavy Trucks - Local", "Heavy Trucks - Interstate/Long Haul",
        "Extra Heavy Trucks - Local", "Extra Heavy Trucks - Interstate/Long Haul",
        "Tractors - Local", "FL", "Limousines",
        "School Bus 1-8 passengers", "School Bus 9-20 passengers",
        "School Bus 21-60 passengers", "School Bus 60+ passengers",
    ]
    vehicle_count = 0
    for key in GENERIC_AUTO_KEYS:
        val = auto.get(key, "0")
        try:
            v = int(str(val).strip()) if val and str(val).strip() != "0" else 0
            vehicle_count += v
        except (ValueError, TypeError):
            pass
    if vehicle_count > 0:
        exposure_top += '<tr><td style="color:#999;">Total Vehicles</td><td>' + str(vehicle_count) + '</td></tr>'

    cov_rows_html = ""
    for cov_type in ["General Liability", "Auto Liability", "Employers Liability", "Employee Benefits", "Umbrella"]:
        carrier_cov = esc(get(coverage, cov_type + " - Carrier", ""))
