        premium = get(coverage, cov_type + " - Premium", "")
        if carrier_cov or limits:
            premium_display = "$" + esc(premium) if premium and premium != "0" else "\u2014"
            cov_rows_html += '<tr><td style="font-weight:500;">' + esc(cov_type) + '</td><td>' + carrier_cov + '</td><td>' + limits + '</td><td>' + premium_display + '</td></tr>'

    exp_carrier = esc(get(expiring, "Expiring Carrier", ""))
    exp_limit = esc(get(expiring, "Expiring Limit", ""))
