        if exp_limit:
            expiring_html += '<tr><td style="color:#999;">Expiring Limit</td><td>$' + exp_limit + '</td></tr>'
        if exp_premium:
            expiring_html += '<tr><td style="color:#999;">Expiring Premium</td><td>$' + exp_premium + '</td></tr>'

    # ── Loss Information ──

    total_incurred = 0
    if agg_loss:
        for rec in agg_loss:
            ti = rec.get("total_incurred", 0)
            try:
                total_incurred += float(str(ti).replace("$", "").replace(",", "").strip()) if ti else 0
            except (ValueError, TypeError):
                pass
        loss_text = '<b>' + str(len(agg_loss)) + '</b> policy periods with total incurred losses of <b>$' + f"{total_incurred:,.0f}" + '</b>'
