    h += '<div class="card"><details open>'
    h += '<summary class="card-header"><span class="card-title">Loss Information</span>' + loss_badge + '</summary>'
    h += '<div class="detail-body card-body"><div style="font-size:13px;color:#1a1a1a;">' + loss_text + '</div></div>'
    h += '</details></div>'

    # Guideline Checks
