    h += '<div style="margin-bottom:8px;"><a href="' + execution_url + '">View Complete Submission &rarr;</a></div>'
    h += 'FurtherAI &middot; ABC MGA Submission Summary'
    h += '</div>'

    h += '</div></body></html>'

